Yes, I can help you with that. Here's the C++ code for a function that calculates the height of a binary tree:
```c++
#include <iostream>
using namespace std;
// Define the structure of a node in the binary tree
struct Node {
    int data;
    Node* left;
    Node* right;
};
// Function to create a new node in the binary tree
Node* newNode(int data) {
    Node* node = new Node;
    node->data = data;
    node->left = NULL;
    node->right = NULL;
    return node;
}
// Function to calculate the height of the binary tree
int height(Node* node) {
    if (node == NULL) {
        return 0;
    } else {
        int leftHeight = height(node->left);
        int rightHeight = height(node->right);
        if (leftHeight > rightHeight) {
            return (leftHeight + 1);
        } else {
            return (rightHeight + 1);
        }
    }
}
// Main function to test the height function
int main() {
    Node* root = newNode(4);
    root->left = newNode(2);
    root->right = newNode(5);
    root->left->left = newNode(1);
    root->left->right = newNode(3);
    root->right->left = newNode(6);
    root->right->right = newNode(7);
    cout << "Height of the binary tree is: " << height(root) << endl;
    return 0;
}
```
This code defines a `Node` structure that represents a node in the binary tree. The `newNode` function is used to create a new node with the given data. The `height` function recursively calculates the height of the binary tree by finding the height of the left and right subtrees and returning the maximum height plus one. Finally, the `main` function creates a binary tree with the given structure and calls the `height` function to calculate the height of the tree.

