Sure, here's an example C++ code that implements a program to check if a given string is a palindrome or not using recursive functions:
```c++
#include <iostream>
#include <string>
using namespace std;
bool isPalindrome(string str, int start, int end) {
    // Base case: if start and end meet in the middle, it's a palindrome
    if (start >= end) {
        return true;
    }
    // Recursive case: compare the characters at start and end, then move inward
    if (str[start] == str[end]) {
        return isPalindrome(str, start + 1, end - 1);
    }
    else {
        return false;
    }
}
int main() {
    string str;
    cout << "Enter a string: ";
    getline(cin, str);
    if (isPalindrome(str, 0, str.length() - 1)) {
        cout << "The string is a palindrome." << endl;
    }
    else {
        cout << "The string is not a palindrome." << endl;
    }
    return 0;
}
```
The `isPalindrome` function takes in a string `str`, a starting index `start`, and an ending index `end`. It first checks if `start` and `end` have met in the middle, in which case it returns `true` (base case). Otherwise, it checks if the characters at `start` and `end` are equal. If they are, it recursively calls `isPalindrome` with `start+1` and `end-1`. If they are not equal, it returns `false`. The `main` function simply prompts the user for a string, calls `isPalindrome`, and outputs the result.

