```swift
func angleBetweenSecondHandAndMinuteHand(time: String) -> Double? {
    let components = time.split(separator: ":").compactMap { Double($0) }
    guard components.count == 3 else { return nil }
    let hour = components[0]
    let minute = components[1]
    let second = components[2]
    let minuteAngle = (minute * 6.0) + (second * 0.1)
    let secondAngle = second * 6.0
    var angle = abs(minuteAngle - secondAngle)
    if angle > 180.0 {
        angle = 360.0 - angle
    }
    return round(angle * 10) / 10
}
```
