function sumWithoutPrimes(arr) {
  // Check if a number is prime
  function isPrime(num) {
    if (num <= 1) return false;
    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) return false;
    }
    return true;
  }
  // Calculate the sum and exclude primes
  let sum = 0;
  const table = [];
  for (let i = 0; i < arr.length; i++) {
    const num = arr[i];
    if (!isPrime(num)) {
      sum += num;
    }
    table.push([num, sum]);
  }
  // Output the table
