```swift
class SightsViewController: UIViewController, UITableViewDataSource, UITableViewDelegate {

    @IBOutlet weak var tableView: UITableView!

    override func viewDidLoad() {
        super.viewDidLoad()

        sights.append(Sight(name: "Colosseum", image: UIImage(named: "colosseum.jpg")!, description: "An ancient amphitheater in Rome, Italy"))
        sights.append(Sight(name: "Pantheon", image: UIImage(named: "pantheon.jpg")!, description: "A former Roman temple, now a church in Rome, Italy"))
        sights.append(Sight(name: "Trevi Fountain", image: UIImage(named: "trevi-fountain.jpg")!, description: "A fountain in Rome, Italy"))

        tableView.dataSource = self
        tableView.delegate = self
    }

    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return sights.count
    }

    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "SightTableViewCell", for: indexPath) as! SightTableViewCell

        let sight = sights[indexPath.row]
        cell.nameLabel.text = sight.name
        cell.sightImageView.image = sight.image
        cell.descriptionLabel.text = sight.description

        return cell
    }

    func tableView(_ tableView: UITableView, commit editingStyle: UITableViewCell.EditingStyle, forRowAt indexPath: IndexPath) {
        if editingStyle == .delete {
            sights.remove(at: indexPath.row)
            tableView.deleteRows(at: [indexPath], with: .fade)
        }
    }

    @IBAction func addSight(_ sender: Any) {
        sights.append(Sight(name: "New Sight", image: UIImage(named: "placeholder.jpg")!, description: "Description"))
        let indexPath = IndexPath(row: sights.count - 1, section: 0)
        tableView.insertRows(at: [indexPath], with: .automatic)
        tableView.scrollToRow(at: indexPath, at: .bottom, animated: true)
    }
}
```
In this example, the table view displays the name, image, and description of each sight. The commit editingStyle method allows the user to delete sights from the table view. The addSight method adds a new sight to the array and inserts a new row into the table view.
